import { cn } from "@/lib/utils";
import { logoPaths } from "./logo-paths";

/**
 * The HEAL logo, inline from the supplied vector (public/brand/healmedllc-sg.svg,
 * paths generated by scripts/build-logo.mjs). Fills use `currentColor`, so the
 * logo takes the text colour of wherever it sits.
 *
 * - `variant="full"`: mark + HEAL + MEDICAL LLC.
 * - `variant="mark"`: the H circle only (page transition, icons).
 * - `animated`: adds the hooks the preloader's CSS animates: `.logo-mark`
 *   (with pathLength 1, so its outline can be drawn), `.logo-letter` with
 *   `--i` inside a clip so the letters rise from behind a mask, `.logo-sub`.
 *   Use it once per page (the clip has a fixed id).
 *
 * Decorative by default; pass `title` to make it an image with a name.
 */
export function Logo({
  variant = "full",
  animated = false,
  title,
  className,
}: {
  variant?: "full" | "mark";
  animated?: boolean;
  title?: string;
  className?: string;
}) {
  const { viewBox, mark, word, sub } = logoPaths;

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={variant === "mark" ? viewBox.mark : viewBox.full}
      fill="currentColor"
      className={cn("block", className)}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
    >
      {animated && (
        <defs>
          {/* Mask for the HEAL letters (bounds 205,230.6 → 400.4,270.4). */}
          <clipPath id="logo-word-clip">
            <rect x="200" y="226" width="206" height="48" />
          </clipPath>
        </defs>
      )}
      <path
        d={mark}
        className={animated ? "logo-mark" : undefined}
        pathLength={animated ? 1 : undefined}
      />
      {variant === "full" && (
        <>
          <g clipPath={animated ? "url(#logo-word-clip)" : undefined}>
            {word.map((d, i) => (
              <path
                key={i}
                d={d}
                className={animated ? "logo-letter" : undefined}
                style={animated ? ({ "--i": i } as React.CSSProperties) : undefined}
              />
            ))}
          </g>
          <g className={cn("opacity-80", animated && "logo-sub")}>
            {sub.map((d, i) => (
              <path key={i} d={d} />
            ))}
          </g>
        </>
      )}
    </svg>
  );
}
